import{_ as t,o,c as a,ag as n}from"./chunks/framework.BIas3y6W.js";const c=JSON.parse('{"title":"Week 3 Homework","description":"","frontmatter":{"source":"weeks/03-prompting-and-save-points/homework.md"},"headers":[],"relativePath":"weeks/03-prompting-and-save-points/homework.md","filePath":"weeks/03-prompting-and-save-points/homework.md"}'),r={name:"weeks/03-prompting-and-save-points/homework.md"};function i(s,e,d,h,l,m){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="week-3-homework" tabindex="-1">Week 3 Homework <a class="header-anchor" href="#week-3-homework" aria-label="Permalink to &quot;Week 3 Homework&quot;">​</a></h1><blockquote><p><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before). <strong>Core:</strong> about 5 hours plus the journal, required. <strong>Stretch:</strong> optional. Graded on effort and completion of the core tier (<a href="./../../assessment/rubrics.html#weekly-labs-and-homework">rubric</a>). &quot;On Canvas&quot; means the course&#39;s learning management system, not Gemini&#39;s Canvas tool.</p></blockquote><p>Use the <a href="./../../resources/safe-loop.html">Safe Loop</a> for every change: Describe → Plan → Step → Test → Read → Commit.</p><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><ul><li>☐ My game works at <code>https://[your-username].github.io/game/</code> through every step of my plan (or I&#39;ve recorded the blocker in <code>PROMPTS.md</code>), with one commit per working step; each AI-helped commit ends with an <code>Assisted-by:</code> line (task 1).</li><li>☐ I fixed the first thing my play-tester found and at least one edge case, and my home page links to the game by name (task 2).</li><li>☐ <code>PROMPTS.md</code> has my three diff readings (🔴 AI off) and my giant-prompt experiment (tasks 3 and 4).</li><li>☐ <code>PROMPTS.md</code> has this week&#39;s entries in four-part form (task 6).</li><li>☐ On Canvas: my <strong>weekly reflection</strong> (🔴 AI off), including the paragraph on the reading (tasks 5 and 7).</li></ul><h2 id="time-plan" tabindex="-1">Time plan <a class="header-anchor" href="#time-plan" aria-label="Permalink to &quot;Time plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Kind</th><th>Time</th></tr></thead><tbody><tr><td>1. Finish your game</td><td>Project time</td><td>2 h</td></tr><tr><td>2. Play-test, edge cases and the link</td><td>Homework</td><td>1 h</td></tr><tr><td>3. Read three diffs</td><td>Homework</td><td>30 min</td></tr><tr><td>4. The giant-prompt experiment</td><td>Homework</td><td>1 h</td></tr><tr><td>5. Reading</td><td>Homework</td><td>30 min</td></tr><tr><td>6. <code>PROMPTS.md</code></td><td>Journal</td><td>15 min</td></tr><tr><td>7. Weekly reflection</td><td>Journal</td><td>20 min</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>about 5½ h</strong></td></tr></tbody></table><p>Before next week&#39;s Studio A, also do the &quot;Before class&quot; list on the <a href="./../04-undo-compare-explain/">week 4 page</a> (up to 30 minutes).</p><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><h3 id="1-finish-your-game-2-h" tabindex="-1">1. Finish your game (2 h) <a class="header-anchor" href="#1-finish-your-game-2-h" aria-label="Permalink to &quot;1. Finish your game (2 h)&quot;">​</a></h3><p>🟢 AI on.</p><p>Pick up where the timer stopped. For each remaining step: one step prompt with your <strong>current</strong> file pasted in, test it against its &quot;Done when&quot; and one edge case, read the diff, and commit with an <code>Assisted-by:</code> line. Two failed fixes? Use the <strong>two-strikes rule</strong>.</p><p>✅ <strong>Checkpoint:</strong> <code>https://[your-username].github.io/game/</code> works through step 5, and the file&#39;s <strong>History</strong> has one clear commit per working step.</p><h3 id="2-play-test-edge-cases-and-the-link-1-h" tabindex="-1">2. Play-test, edge cases and the link (1 h) <a class="header-anchor" href="#2-play-test-edge-cases-and-the-link-1-h" aria-label="Permalink to &quot;2. Play-test, edge cases and the link (1 h)&quot;">​</a></h3><p>🟢 AI on for the fixes · 🔴 AI off for the link text.</p><ol><li>Fix the first thing that confused your play-tester in Studio B, with a step prompt (Goal: fix [problem]; Context: the complete file; Constraints: change only that; Done when: the problem no longer happens and everything else still works). Test, read the diff, and commit as <code>Fix: [what you fixed]</code>. No play-tester? Ask someone at home to play it for two minutes without help.</li><li>Test <strong>three edge cases</strong> and fix at least one that breaks. Ideas: restart twice in a row; press keys that aren&#39;t controls; make the window very narrow; click very fast; lose on purpose in the first second.</li><li><strong>By hand</strong> (🔴 AI off), in github.dev, open your home page&#39;s <code>index.html</code> and find the Projects link to <code>game/</code>. Change its text from the placeholder to your game&#39;s name, for example <code>Snake, built in one hour</code>. Commit: <code>Link game from home page</code> (no <code>Assisted-by:</code> line: you did it yourself).</li></ol><p>✅ <strong>Checkpoint:</strong> clicking the Projects link on your live home page opens your game, and its History has at least one <code>Fix:</code> commit.</p><h3 id="3-read-three-diffs-30-min" tabindex="-1">3. Read three diffs (30 min) <a class="header-anchor" href="#3-read-three-diffs-30-min" aria-label="Permalink to &quot;3. Read three diffs (30 min)&quot;">​</a></h3><p>🔴 AI off until the last step.</p><p><strong>Why:</strong> Simon Willison&#39;s golden rule (task 5) is to commit only code you could explain to someone else. Reading your own diffs is practice for that, and for next week&#39;s peer explanation swap.</p><ol><li>On github.com, open <code>game/index.html</code> → <strong>History</strong>, and pick three of your step commits.</li><li>For each one, click it and read the red and green lines. In <code>PROMPTS.md</code>, under a heading <strong>Diffs I read</strong>, write two lines: <ul><li><strong>What changed in the code</strong>, in your own words (for example: &quot;added a <code>score</code> variable and a line in <code>eatFood()</code> that adds 1 to it&quot;).</li><li><strong>Does the commit message say so?</strong> If not, write the message you&#39;d use now.</li></ul></li><li>If there&#39;s a change you can&#39;t explain, mark it <strong>?</strong>. Only then ask your assistant to explain that part of the diff, and add one sentence on what you learned.</li></ol><p>This is a first taste of the <strong><a href="./../../resources/safe-loop.html#teach-back">teach-back</a></strong>: from next week you write two or three sentences like these <strong>before</strong> each AI-helped commit.</p><h3 id="4-the-giant-prompt-experiment-1-h" tabindex="-1">4. The giant-prompt experiment (1 h) <a class="header-anchor" href="#4-the-giant-prompt-experiment-1-h" aria-label="Permalink to &quot;4. The giant-prompt experiment (1 h)&quot;">​</a></h3><p>🟢 AI on.</p><p><strong>Why:</strong> the study in the <a href="./#small-steps-and-two-strikes">Key ideas</a> found that one giant prompt does best on the first try and worst when the code has to change. Test that on your own game.</p><ol><li>In a <strong>fresh chat</strong>, ask for your whole game in one prompt: paste the five steps of your plan and ask for the finished game in one file.</li><li>Test it against your five &quot;Done when&quot; lines. Write down how many pass.</li><li>In the same chat, ask for one change your play-tester wanted (or the fix from task 2). Test again: did anything that worked before break?</li><li>Compare it with the version you built in steps. Under a heading <strong>Giant-prompt experiment</strong> in <code>PROMPTS.md</code>, write 4–6 sentences: how many checks passed first time, what happened when you asked for a change, which version you could explain more of, and which one you&#39;d rather keep changing.</li></ol><p>Don&#39;t commit the giant version into <code>game/index.html</code>. If you want to keep it, save it as <code>game/giant.html</code> and commit it with an <code>Assisted-by:</code> line.</p><h3 id="5-reading-30-min" tabindex="-1">5. Reading (30 min) <a class="header-anchor" href="#5-reading-30-min" aria-label="Permalink to &quot;5. Reading (30 min)&quot;">​</a></h3><p>Read Simon Willison&#39;s <a href="https://simonwillison.net/2025/Mar/19/vibe-coding/" target="_blank" rel="noreferrer">&quot;Not all AI-assisted programming is vibe coding (but vibe coding rocks)&quot;</a> (about 20 minutes). It&#39;s the post behind the course&#39;s golden rule. Then add a short paragraph to your reflection (task 7): in your own words, what is his golden rule, and describe one moment this week when you followed it or broke it.</p><h3 id="6-promptsmd-15-min" tabindex="-1">6. <code>PROMPTS.md</code> (15 min) <a class="header-anchor" href="#6-promptsmd-15-min" aria-label="Permalink to &quot;6. `PROMPTS.md` (15 min)&quot;">​</a></h3><p>🟢 AI on for formatting · 🔴 AI off for &quot;What I wrote or decided myself&quot;.</p><p>Add a <strong>Week 3</strong> heading, with the prompts written in four-part form (<strong>Goal · Context · Constraints · Done when</strong>):</p><ul><li>your Studio A practice prompt, and the link to its <code>Assisted-by:</code> commit;</li><li>your plan prompt, and how you changed the plan;</li><li>at least three step prompts, including one that failed and what you did next;</li><li>the play-test: what confused your tester, and your fix;</li><li>your diff readings (task 3) and the giant-prompt experiment (task 4).</li></ul><p>Update <strong>What I wrote or decided myself</strong> (the link text, and any change you made by hand) and <strong>What I&#39;d prompt differently next time</strong>. Commit with a clear message.</p><h3 id="7-weekly-reflection-20-min" tabindex="-1">7. Weekly reflection (20 min) <a class="header-anchor" href="#7-weekly-reflection-20-min" aria-label="Permalink to &quot;7. Weekly reflection (20 min)&quot;">​</a></h3><p>🔴 AI off.</p><p>Answer the four questions in the <a href="./../../templates/REFLECTION.html">reflection template</a> in 150–300 words, plus the reading paragraph from task 5, <strong>without AI</strong>. Good moments to write about: the buzzer, a step that took two strikes, or what the giant-prompt experiment showed you. Submit it on <strong>Canvas</strong>, not in your repository (<a href="./../../assessment/#privacy-of-your-work">Privacy of your work</a>).</p><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><p>Each of these is a small Safe Loop of its own. Commit before you start and after each working step, with <code>Assisted-by:</code> lines, and log your prompts in <code>PROMPTS.md</code>.</p><ul><li><strong>A ★★★ Hard game</strong> from the <a href="./game-menu.html">game menu</a>, as a second game in <code>game2/index.html</code>, linked from your Projects section.</li><li><strong>Read the study behind &quot;small steps&quot;:</strong> <a href="https://arxiv.org/abs/2309.14049" target="_blank" rel="noreferrer">Kazemitabaar et al. (Koli Calling 2023)</a>. Read the abstract and the conclusion. Does it match what your giant-prompt experiment showed?</li></ul><hr><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> your game is at <code>/game/</code> with at least three working-step commits. Next week you break it on purpose and restore it from those save points, compare two AI models on its next change, and write your first automated test for one of its functions. If it isn&#39;t working, ask your instructor for help before Studio A.</p></div>',42)])])}const g=t(r,[["render",i]]);export{c as __pageData,g as default};
